s = s.replace("SRRxxxxxxx", "SRR8114121")
s = s.replace("| TODO |", "| see 03_results/sample_metaphlan.txt |")
s = re.sub(r"\s*\[add the sequence\(s\)[^\]]*\]", "", s)
